<?php namespace App\Http\Controllers; use App\Models\{ActivationHistory,Organization,PaymentRequest,User}; use Illuminate\Http\Request; class AdminController extends Controller { public function index(){return view('admin.index',['pending'=>Organization::where('status','pending')->get(),'payments'=>PaymentRequest::with('organization')->where('status','pending')->get(),'expiring'=>Organization::where('subscription_until','<',now()->addDays(7))->where('status','active')->get()]);} public function approve(Organization $organization){abort_unless($organization->status==='pending',422);$history=ActivationHistory::where('phone',$organization->phone)->first();$until=$history?->demo_used_at?->copy()->addDay();if(!$history?->demo_used_at){$history?->update(['demo_used_at'=>now()]);$until=now()->addDay();}$organization->update(['status'=>'active','subscription_until'=>$until]);$organization->users()->update(['approved_at'=>now()]);return back()->with('success','Организация одобрена.');} public function payment(PaymentRequest $payment,Request $r){$d=$r->validate(['action'=>'required|in:approve,reject','note'=>'nullable|string|max:1000']);$payment->update(['status'=>$d['action']==='approve'?'approved':'rejected','admin_note'=>$d['note']??null,'reviewed_by'=>$r->user()->id]);if($d['action']==='approve'){$org=$payment->organization;$org->update(['subscription_until'=>max(now(),$org->subscription_until??now())->addDays($payment->days),'status'=>'active']);}return back()->with('success','Запрос обработан.');} public function users(){return view('admin.users',['users'=>User::with('organization')->paginate(30)]);} public function toggleBlock(User $user){abort_if($user->isAdmin(),422);$user->update(['is_blocked'=>!$user->is_blocked]);return back();} }
